WidgetsFlutterBinding.ensureInitialized();
await SplunkRum.instance.install(
  agentConfiguration: AgentConfiguration(
    endpoint: EndpointConfiguration.forRum(
      realm: realm,
      rumAccessToken: rumAccessToken,
    ),
    appName: appName,
    deploymentEnvironment: deploymentEnvironment,
  ),
  moduleConfigurations: [
    CrashReportsModuleConfiguration(),
    NavigationModuleConfiguration(),
    NetworkMonitorModuleConfiguration(),
    SlowRenderingModuleConfiguration(),
    AnrModuleConfiguration(),
    SessionReplayModuleConfiguration(samplingRate: 1.0),
  ],
);
// The module configuration only enables session replay; recording itself
// must be started explicitly.
await SplunkSessionReplay.instance.start();
runApp(const MyApp());

// Splunk has no renameable per-step label like AppDynamics' SessionFrame.
// A named workflow span is the closest analog for labeling a step.
final workflow = await SplunkRum.instance.customTracking.startWorkflow(
  name: 'Journey Map Demo',
);

// Call this when the screen/flow ends (e.g. dispose(), route pop).
await workflow.end();

// splunk_otel_flutter has no manual session-rollover API.
// SplunkRum.instance.session only exposes read-only state:
final id = await SplunkRum.instance.session.state.getId();
final samplingRate = await SplunkRum.instance.session.state.getSamplingRate();

// No dedicated breadcrumb API; a named custom event is the closest analog.
await SplunkRum.instance.customTracking.trackCustomEvent(
  name: 'breadcrumb',
  attributes: MutableAttributes(
    attributes: {'value': MutableAttributeString(value: 'flutter-sample')},
  ),
);

// Global attributes attach to all telemetry sent after they are set.
final attributes = SplunkRum.instance.globalAttributes;
await attributes.setString(key: 'sample_user_tier', value: 'gold');
await attributes.setInt(key: 'sample_retry_count', value: 3);
await attributes.setBool(key: 'sample_premium_feature', value: true);

// Screenshot capture is not part of the core SDK.
// See the separate splunk_otel_flutter_session_replay package for
// screen-recording session replay instead.

// splunk_otel_flutter has no Dart-level tracked HTTP client; automatic
// network instrumentation wraps native OkHttp/HttpURLConnection (Android)
// and NSURLSession (iOS), not package:http.
final client = http.Client();
final response = await client.get(Uri.parse(url));

// iOS only: exclude matching URLs from native network tracing.
NetworkInstrumentationModuleConfiguration(
  ignoreURLs: [RegularExpression(pattern: 'https://internal\\.example\\.com/.*')],
);
// Android has no URL-exclusion API exposed by splunk_otel_flutter 1.2.0.

try {
  await readRequiredFile();
} catch (error, stackTrace) {
  await SplunkRum.instance.customTracking.trackError(
    error,
    stackTrace: stackTrace,
    handled: true,
  );
}

// No manual ANR trigger exists; block the engine thread so the native
// ANR/app-hang watchdog (AnrModuleConfiguration, Android) detects it.
if (kDebugMode) {
  sleep(const Duration(seconds: 6));
}

// splunk_otel_flutter has no Dart-level API to force a native process
// crash, so this invokes a small native MethodChannel (MainActivity.kt /
// AppDelegate.swift) that raises a real exception outside Dart.
// CrashReportsModuleConfiguration's native crash handler captures it and
// uploads the report on the next app launch.
const _nativeCrashChannel = MethodChannel('splunk_sample/native_crash');

if (kDebugMode || kProfileMode) {
  await _nativeCrashChannel.invokeMethod<void>('crash');
}

// FlutterError.onError alone misses uncaught ASYNC errors.
// Wrap runApp in a zone so those are reported too.
runZonedGuarded(
  () => runApp(const MyApp()),
  (error, stackTrace) => SplunkRum.instance.customTracking.trackError(
    error,
    stackTrace: stackTrace,
    handled: false,
    source: ErrorSource.source,
  ),
);

// Example of an error that bypasses FlutterError.onError:
if (kDebugMode) {
  Future.microtask(() => throw StateError('Unhandled async error.'));
}

final status = await SplunkSessionReplay.instance.getStatus();
// status is one of: isRecording, notStarted, stopped,
// belowMinSdkVersion, storageLimitReached, internalError, disabledBySampling.
print('Session replay status: ${status.name}');

// Cover a rectangular region so it never appears in the replay.
await SplunkSessionReplay.instance.setRecordingMask(
  mask: RecordingMask(
    elements: [
      MaskElement(
        rect: const Rect.fromLTWH(0, 0, 200, 80),
        type: MaskType.covering,
      ),
    ],
  ),
);

// Clear the mask when it's no longer needed.
await SplunkSessionReplay.instance.setRecordingMask(mask: null);
